architecture mixed of demo is
  signal sum, cout : std_logic;
  signal count     : unsigned(3 downto 0) := "0000";
begin
  -- Concurrent: half-adder
  sum  <= a xor b;    -- line 7
  cout <= a and b;    -- line 8

  -- Sequential: 4-bit counter
  process(clk)
  begin
    if rising_edge(clk) then
      count <= count + 1;
    end if;
  end process;
end architecture;
